from typing import List

class Solution:
    def braceExpansionII(self, expression: str) -> List[str]:
        def expand(exp):
            if len(exp) == 1:
                return {exp}
            if exp[0] == '{':
                words = set()
                i = 1
                while i < len(exp):
                    if exp[i] == '}':
                        i += 1
                        break
                    elif exp[i] == '{':
                        words.update(expand(exp[i:]))
                        i += 1
                    elif exp[i].isalpha():
                        words.update(expand(exp[i:i+1]))
                        i += 1
                    else:
                        i += 1
                return words
            else:
                return expand(exp[1:])

        words = expand(expression)
        return sorted(words)
