from typing import List

class Solution:
    def braceExpansionII(self, expression: str) -> List[str]:
        def parse(expr: str) -> List[str]:
            # Base case: single character
            if len(expr) == 1:
                return [expr]

            # Find the innermost set
            depth = 0
            for i in range(len(expr)):
                if expr[i] == '{':
                    depth += 1
                elif expr[i] == '}':
                    depth -= 1
                elif expr[i] == ',' and depth == 0:
                    return parse(expr[:i]) + parse(expr[i+1:])

            # If no comma found, it's a simple set
            return parse(expr[1:-1])

        # Start parsing
        return sorted(set(parse(expression)))
